A row that cannot be imported goes in `errors` and is left out of `users`. A file with
unimportable rows still imports the rows that are fine.
"""
result = ImportResult()
reader = csv.reader(io.StringIO(csv_text))

try:
    header = next(reader)
except StopIteration:
    result.errors.append("file is empty")
    return result
except csv.Error as exc:
    result.errors.append(f"could not parse header row: {exc}")
    return result

header = [column.strip() for column in header]
missing_columns = [c for c in REQUIRED_COLUMNS if c not in header]
if missing_columns:
    result.errors.append(
        f"missing required column(s): {', '.join(missing_columns)}"
    )
    return result

while True:
    try:
        row = next(reader)
    except StopIteration:
        break
    except csv.Error as exc:
        result.errors.append(f"row {reader.line_num}: could not parse ({exc})")
        continue

    line_num = reader.line_num

    if not row or all(not field.strip() for field in row):
        continue  # blank line, not an error

    if len(row) != len(header):
        result.errors.append(
            f"row {line_num}: expected {len(header)} columns, got {len(row)}"
        )
        continue

    record = dict(zip(header, row))

    empty_required = [
        c for c in REQUIRED_COLUMNS if not record.get(c, "").strip()
    ]
    if empty_required:
        result.errors.append(
            f"row {line_num}: missing value for {', '.join(empty_required)}"
        )
        continue

    result.users.append(record)

return result

